import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { hogql } from '~/queries/utils'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sessionVolumeLogicValues {
    weeklySessions: number | null
    weeklySessionsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sessionVolumeLogicActions {
    loadWeeklySessions: () => any
    loadWeeklySessionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadWeeklySessionsSuccess: (
        weeklySessions: number | null,
        payload?: any
    ) => {
        weeklySessions: number | null
        payload?: any
    }
}

export type sessionVolumeLogicType = MakeLogicType<sessionVolumeLogicValues, sessionVolumeLogicActions>

/** Recent total session volume, used to project how many recordings a sample rate will produce. */
export const sessionVolumeLogic = kea<sessionVolumeLogicType>([
    path(['scenes', 'settings', 'environment', 'sessionVolumeLogic']),
    loaders({
        // Sessions in the last 7 days, so the value already reads as a per-week figure.
        weeklySessions: [
            null as number | null,
            {
                loadWeeklySessions: async () => {
                    const response = await api.queryHogQL(
                        hogql`SELECT count() FROM sessions WHERE $start_timestamp >= now() - INTERVAL 7 DAY`,
                        { scene: 'ReplayTriggers', productKey: 'session_replay' }
                    )
                    const count = response.results?.[0]?.[0]
                    return typeof count === 'number' ? count : null
                },
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadWeeklySessions()
    }),
])
